<?php
require_once __DIR__ . '/auth.php';
requireAdmin();
$me = $_SESSION['auth_user'];
$name = $me['name'] ?: 'Administrator';
$initials = strtoupper(substr(preg_replace('/[^A-Za-z0-9]/', '', $name), 0, 2));
?>
<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Admin Dashboard — Ujian ASTS</title>
