<style>
:root{--ink:#111827;--muted:#6b7280;--line:#e5e7eb;--bg:#f5f7fb;--accent:#4f46e5;--accent2:#4338ca;--danger:#dc2626;--dangerbg:#fef2f2;--green:#059669;--greenbg:#ecfdf5;--amber:#d97706;--amberbg:#fffbeb;--sidebar:245px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,Arial,sans-serif}.app{min-height:100vh;display:flex}.sidebar{position:fixed;inset:0 auto 0 0;width:var(--sidebar);background:#111827;color:#fff;padding:22px 15px;display:flex;flex-direction:column;z-index:10}.brand{display:flex;align-items:center;gap:11px;padding:6px 8px 25px}.mark{width:42px;height:42px;border-radius:12px;background:linear-gradient(135deg,#6366f1,#4338ca);display:grid;place-items:center;font-weight:800}.brand strong{display:block;font-size:14px}.brand span{font-size:10px;color:#9ca3af}.nav-label{font-size:9px;text-transform:uppercase;letter-spacing:.14em;color:#6b7280;font-weight:800;margin:8px 9px}.nav{display:grid;gap:5px}.nav a{color:#cbd5e1;text-decoration:none;padding:11px 12px;border-radius:10px;font-size:11px;font-weight:700;display:flex;gap:10px;align-items:center}.nav a.active,.nav a:hover{background:#1f2937;color:#fff}.sidefoot{margin-top:auto;border-top:1px solid #1f2937;padding-top:14px}.profile{display:flex;gap:10px;align-items:center;padding:8px}.avatar{width:34px;height:34px;border-radius:10px;background:#312e81;display:grid;place-items:center;font-size:10px;font-weight:800}.profile strong{display:block;font-size:10px}.profile span{display:block;font-size:9px;color:#9ca3af;max-width:145px;overflow:hidden;text-overflow:ellipsis}.logout{display:flex;gap:9px;color:#fca5a5;text-decoration:none;font-size:10px;font-weight:800;padding:10px 8px}.main{margin-left:var(--sidebar);width:calc(100% - var(--sidebar))}.top{height:68px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 30px;position:sticky;top:0;z-index:5}.crumb{font-size:11px;color:var(--muted)}.crumb strong{color:var(--ink)}.topright{display:flex;gap:8px}.iconbtn{width:36px;height:36px;border:1px solid var(--line);border-radius:10px;background:#fff;cursor:pointer;color:#374151}.page{padding:32px;max-width:1400px;margin:auto}.head{display:flex;justify-content:space-between;gap:20px;align-items:flex-end}.eyebrow{font-size:10px;color:var(--accent);font-weight:800;text-transform:uppercase;letter-spacing:.14em}.head h1{font-size:30px;margin:6px 0}.head p{margin:0;color:var(--muted);font-size:12px}.buttons{display:flex;gap:8px;flex-wrap:wrap}.btn{border:0;border-radius:10px;padding:10px 14px;font-size:11px;font-weight:800;cursor:pointer}.primary{background:var(--accent);color:#fff}.primary:hover{background:var(--accent2)}.danger{background:var(--dangerbg);color:#b91c1c}.light{background:#fff;border:1px solid var(--line);color:#374151}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:25px 0}.stat{background:#fff;border:1px solid var(--line);border-radius:16px;padding:17px}.stat .label{font-size:10px;color:var(--muted);font-weight:700}.stat .value{font-size:26px;font-weight:800;margin-top:6px}.panel{background:#fff;border:1px solid var(--line);border-radius:18px;overflow:hidden}.panelhead{padding:18px 20px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:15px;align-items:center}.panelhead h2{font-size:15px;margin:0}.panelhead p{font-size:10px;color:var(--muted);margin:5px 0 0}.search{height:38px;border:1px solid var(--line);border-radius:9px;display:flex;align-items:center;padding:0 10px;gap:8px;min-width:260px}.search input{border:0;outline:0;width:100%;font-size:11px}.tablewrap{overflow:auto}.table{width:100%;border-collapse:collapse;min-width:850px}.table th{text-align:left;background:#f9fafb;color:#6b7280;font-size:9px;text-transform:uppercase;letter-spacing:.05em;padding:12px 16px;border-bottom:1px solid var(--line)}.table td{padding:13px 16px;border-bottom:1px solid #f3f4f6;font-size:11px;vertical-align:middle}.table tr:last-child td{border-bottom:0}.usercell{display:flex;align-items:center;gap:9px}.mini{width:34px;height:34px;border-radius:10px;background:#eef2ff;color:#4338ca;display:grid;place-items:center;font-size:10px;font-weight:800}.usercell strong{display:block}.usercell span{display:block;color:var(--muted);font-size:9px;margin-top:2px}.badge{display:inline-block;padding:5px 8px;border-radius:7px;font-size:9px;font-weight:800}.badge.user{background:#eef2ff;color:#4338ca}.badge.admin{background:#111827;color:#fff}.actions{display:flex;justify-content:flex-end;gap:5px}.action{width:32px;height:32px;border:1px solid var(--line);border-radius:8px;background:#fff;cursor:pointer}.action.edit{color:#4f46e5}.action.del{color:#dc2626}.empty{text-align:center;padding:40px;color:var(--muted);font-size:11px}.modal{position:fixed;inset:0;background:#11182780;display:none;place-items:center;padding:20px;z-index:30}.modal.show{display:grid}.box{width:min(650px,100%);background:#fff;border-radius:20px;padding:24px;box-shadow:0 25px 80px #0003}.modalhead{display:flex;justify-content:space-between}.modalhead h2{margin:0;font-size:19px}.close{width:34px;height:34px;border:0;border-radius:9px;background:#f3f4f6;cursor:pointer}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}.field.full{grid-column:1/-1}.field label{display:block;font-size:10px;font-weight:800;margin-bottom:6px;color:#374151}.control{width:100%;height:41px;border:1px solid #d1d5db;border-radius:9px;padding:0 11px;font-size:11px;outline:0}.control:focus{border-color:#818cf8;box-shadow:0 0 0 4px #6366f11a}.hint{font-size:9px;color:#9ca3af;line-height:1.5;margin-top:5px}.modalfoot{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}.alert{display:none;margin-top:14px;padding:10px 12px;border-radius:9px;font-size:10px}.alert.show{display:block}.alert.error{background:var(--dangerbg);color:#b91c1c}.alert.success{background:var(--greenbg);color:#047857}.spinner{width:13px;height:13px;border:2px solid #ffffff66;border-top-color:#fff;border-radius:50%;display:inline-block;animation:spin .7s linear infinite;vertical-align:-2px}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:900px){.sidebar{display:none}.main{margin:0;width:100%}.summary{grid-template-columns:1fr 1fr}.page{padding:20px}.head{align-items:flex-start;flex-direction:column}}@media(max-width:600px){.summary{grid-template-columns:1fr}.formgrid{grid-template-columns:1fr}.field.full{grid-column:auto}.top{padding:0 15px}.page{padding:15px}.search{min-width:0;width:100%}.panelhead{align-items:stretch;flex-direction:column}}
</style></head><body><div class="app"><aside class="sidebar"><div class="brand"><div class="mark">UA</div><div><strong>Ujian ASTS</strong><span>Admin Control Center</span></div></div><div class="nav-label">Workspace</div><nav class="nav"><a class="active" href="index.php"><i class="fa-solid fa-users"></i> Manajemen Akun</a><a href="register.php"><i class="fa-solid fa-user-plus"></i> Register User</a></nav><div class="sidefoot"><div class="profile"><div class="avatar"><?=htmlspecialchars($initials ?: 'AD')?></div><div><strong><?=htmlspecialchars($name)?></strong><span><?=htmlspecialchars($me['email'])?></span></div></div><a class="logout" href="logout.php"><i class="fa-solid fa-arrow-right-from-bracket"></i> Keluar</a></div></aside><main class="main"><header class="top"><div class="crumb"><strong>Workspace</strong> / Manajemen Akun</div><div class="topright"><button class="iconbtn" onclick="loadAccounts()" title="Refresh"><i class="fa-solid fa-arrows-rotate"></i></button><a class="iconbtn" href="logout.php" title="Keluar"><i class="fa-solid fa-arrow-right-from-bracket"></i></a></div></header><div class="page"><section class="head"><div><div class="eyebrow">Admin dashboard</div><h1>Manajemen Akun</h1><p>Edit data user, ubah role, dan hapus akun dari satu tempat.</p></div><div class="buttons"><button class="btn primary" onclick="openCreate()"><i class="fa-solid fa-plus"></i> Tambah Akun</button></div></section><section class="summary"><div class="stat"><div class="label">Total akun</div><div class="value" id="total">0</div></div><div class="stat"><div class="label">User</div><div class="value" id="users">0</div></div><div class="stat"><div class="label">Admin</div><div class="value" id="admins">0</div></div><div class="stat"><div class="label">WhatsApp terdaftar</div><div class="value" id="whatsapp">0</div></div></section><section class="panel"><div class="panelhead"><div><h2>Daftar akun</h2><p>Notifikasi perubahan dan penghapusan dikirim ke WhatsApp akun terkait.</p></div><div class="search"><i class="fa-solid fa-magnifying-glass"></i><input id="search" placeholder="Cari nama, email, WhatsApp..." oninput="render()"></div></div><div class="tablewrap"><table class="table"><thead><tr><th>Akun</th><th>Email</th><th>WhatsApp</th><th>Role</th><th>Dibuat</th><th style="text-align:right">Aksi</th></tr></thead><tbody id="body"><tr><td colspan="6" class="empty">Memuat data...</td></tr></tbody></table></div></section></div></main></div>
<div class="modal" id="modal"><div class="box"><div class="modalhead"><div><h2 id="modalTitle">Edit Akun</h2><div class="hint">Jika password dikosongkan, password lama tetap digunakan.</div></div><button class="close" onclick="closeModal()">×</button></div><div id="alert" class="alert"></div><form id="form"><input type="hidden" name="id" id="id"><div class="formgrid"><div class="field full"><label>Nama lengkap</label><input class="control" name="name" id="name" required maxlength="100"></div><div class="field"><label>Email</label><input class="control" name="email" id="email" type="email" required maxlength="150"></div><div class="field"><label>WhatsApp</label><input class="control" name="whatsapp" id="wa" required maxlength="15" inputmode="numeric"></div><div class="field"><label>Role</label><select class="control" name="role" id="role"><option value="user">User</option><option value="admin">Admin</option></select><div class="hint">Perubahan role akan diberitahukan melalui WhatsApp akun.</div></div><div class="field"><label>Password baru (opsional)</label><input class="control" name="password" id="password" type="password" minlength="6" placeholder="Minimal 6 karakter"></div></div><div class="modalfoot"><button type="button" class="btn light" onclick="closeModal()">Batal</button><button class="btn primary" id="save">Simpan Perubahan</button></div></form></div></div>
<script>
let accounts=[], editingId=0;
const meId=<?=json_encode((int)$me['id'])?>;
function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));}
function initials(s){return (String(s||'U').replace(/[^A-Za-z0-9]/g,'').slice(0,2)||'U').toUpperCase();}
function showAlert(msg,type='error'){const e=document.getElementById('alert');e.className='alert show '+type;e.textContent=msg;}
function closeModal(){document.getElementById('modal').classList.remove('show');}
function openCreate(){editingId=0;document.getElementById('modalTitle').textContent='Tambah Akun';document.getElementById('form').reset();document.getElementById('role').value='user';document.getElementById('password').required=true;document.getElementById('password').placeholder='Minimal 6 karakter';document.getElementById('alert').className='alert';document.getElementById('modal').classList.add('show');}
function openEdit(id){const a=accounts.find(x=>Number(x.id)===Number(id));if(!a)return;editingId=Number(id);document.getElementById('modalTitle').textContent='Edit Akun';document.getElementById('id').value=a.id;document.getElementById('name').value=a.name||'';document.getElementById('email').value=a.email||'';document.getElementById('wa').value=a.whatsapp||'';document.getElementById('role').value=a.role||'user';document.getElementById('password').value='';document.getElementById('password').required=false;document.getElementById('alert').className='alert';document.getElementById('modal').classList.add('show');}
async function api(fd){const r=await fetch('account_actions.php',{method:'POST',body:fd});const t=await r.text();let j;try{j=JSON.parse(t)}catch(e){throw new Error('Server mengembalikan respons tidak valid.')}if(!j.success)throw new Error(j.message||'Proses gagal.');return j;}
async function loadAccounts(){try{const fd=new FormData();fd.set('action','admin_list');const j=await api(fd);accounts=j.accounts||[];render();}catch(e){document.getElementById('body').innerHTML='<tr><td colspan="6" class="empty">'+esc(e.message)+'</td></tr>';}}
function render(){const q=(document.getElementById('search').value||'').toLowerCase();const list=accounts.filter(a=>[a.name,a.email,a.whatsapp,a.role].join(' ').toLowerCase().includes(q));document.getElementById('total').textContent=accounts.length;document.getElementById('users').textContent=accounts.filter(a=>a.role==='user').length;document.getElementById('admins').textContent=accounts.filter(a=>a.role==='admin').length;document.getElementById('whatsapp').textContent=accounts.filter(a=>a.whatsapp).length;const body=document.getElementById('body');if(!list.length){body.innerHTML='<tr><td colspan="6" class="empty">Tidak ada akun.</td></tr>';return}body.innerHTML=list.map(a=>`<tr><td><div class="usercell"><div class="mini">${esc(initials(a.name))}</div><div><strong>${esc(a.name||'-')}</strong><span>ID #${esc(a.id)}</span></div></div></td><td>${esc(a.email)}</td><td>${esc(a.whatsapp||'-')}</td><td><span class="badge ${a.role==='admin'?'admin':'user'}">${esc(a.role.toUpperCase())}</span></td><td>${esc(a.created_at||'-')}</td><td><div class="actions"><button class="action edit" title="Edit" onclick="openEdit(${Number(a.id)})"><i class="fa-solid fa-pen"></i></button>${Number(a.id)!==meId?`<button class="action del" title="Hapus" onclick="deleteAccount(${Number(a.id)})"><i class="fa-solid fa-trash"></i></button>`:''}</div></td></tr>`).join('');}
async function deleteAccount(id){const a=accounts.find(x=>Number(x.id)===Number(id));if(!a)return;if(!confirm(`Hapus akun ${a.name}? Notifikasi WhatsApp akan dikirim sebelum akun dihapus.`))return;const fd=new FormData();fd.set('action','admin_delete');fd.set('id',id);try{const j=await api(fd);alert(j.message+(j.notification?.sent?'\nNotifikasi WhatsApp terkirim.':''));loadAccounts();}catch(e){alert(e.message);}}
document.getElementById('form').addEventListener('submit',async e=>{e.preventDefault();const b=document.getElementById('save');b.disabled=true;b.innerHTML='<span class="spinner"></span> Menyimpan';try{const fd=new FormData(e.target);fd.set('action',editingId?'admin_update':'admin_create');if(editingId)fd.set('id',editingId);const j=await api(fd);showAlert(j.message+(j.notification?.sent?' Notifikasi WhatsApp terkirim.':''),'success');setTimeout(()=>{closeModal();loadAccounts();},700);}catch(err){showAlert(err.message,'error')}finally{b.disabled=false;b.textContent='Simpan Perubahan';}});
loadAccounts();
</script></body></html>
